tR(a){return a===0?"\u0644\u0627 \u062a\u0648\u062c\u062f \u062a\u0634\u063a\u064a\u0644\u0627\u062a \u062c\u062f\u064a\u062f\u0629":"\u062a\u0645 \u0627\u0644\u0639\u062b\u0648\u0631 \u0639\u0644\u0649 "+a+" \u062a\u0634\u063a\u064a\u0644\u0629 \u062c\u062f\u064a\u062f\u0629"},
CB(a){return"\u0646\u064f\u0634\u0631 \u0641\u064a "+a},
uL(a){return"\u0625\u0632\u0627\u0644\u0629 @"+a+" \u0645\u0646 \u062d\u0633\u0627\u0628\u0627\u062a\u0643\u061f"},
ux(a){return"\u062a\u0645\u062a \u0625\u0636\u0627\u0641\u0629 @"+a+" \u0628\u0646\u062c\u0627\u062d."},
